#include <bits/stdc++.h>
using namespace std;
#include <atcoder/modint>
using mint = atcoder::modint998244353;
int main()
{
    const int M = 1e7;
    // 線形篩
    vector<int> lpf(M + 1);
    iota(lpf.begin(), lpf.end(), 0);
    vector<int> primes;
    for (int x = 2; x <= M; x++)
    {
        if (lpf[x] == x) primes.push_back(x);
        for (auto p : primes) {
            if ((int64_t)p * x > M || p > lpf[x]) break;
            lpf[p * x] = p;
        }
    }
    int T;
    cin >> T;
    while (T--)
    {
        int N;
        cin >> N;
        vector<int> A(N);
        for (int i = 0; i < N; i++) cin >> A[i];

        // e1[p]=e_1(p), e2[p]=e_2(p)
        map<int, int> e1, e2;
        // e_1(p), e_2(p) を計算
        for (int i = 0; i < N; i++)
        {
            int x = A[i];
            while (x > 1)
            {
                int p = lpf[x], e = 0;
                while (x % p == 0) x /= p, e++;
                if (e > e1[p])
                    e2[p] = e1[p], e1[p] = e;
                else if (e > e2[p])
                    e2[p] = e;
            }
        }

        // LCM(A_1,...,A_N) を計算
        mint lcm = 1;
        for (auto &[p, e] : e1) lcm *= mint(p).pow(e);

        // 答えを計算
        for (int i = 0; i < N; i++)
        {
            mint ans = lcm;
            int x = A[i];
            while (x > 1)
            {
                int p = lpf[x], e = 0;
                while (x % p == 0) x /= p, e++;
                if (e == e1[p]) ans /= mint(p).pow(e1[p] - e2[p]);
            }
            cout << ans.val() << " \n"[i + 1 == N];
        }
    }
}
